175	/****************************************************************************
176	 * Name: bk7258_uart_setup
177	 ****************************************************************************/
178	
179	static int bk7258_uart_setup(struct uart_dev_s *dev)
180	{
181	  static bool initialized;
182	  struct bk7258_uart_s *priv = dev->priv;
183	  const uart_config_t config =
184	    {
185	      .baud_rate = BK7258_UART_BAUD_RATE,
186	      .data_bits = UART_DATA_8_BITS,
187	      .parity = UART_PARITY_NONE,
188	      .stop_bits = UART_STOP_BITS_1,
189	      .flow_ctrl = UART_FLOWCTRL_DISABLE,
190	      .src_clk = UART_SCLK_XTAL_26M,
191	      .rx_dma_en = UART_DMA_DISABLE,
192	      .tx_dma_en = UART_DMA_DISABLE,
193	    };
194	
195	  cold_ckpt("U0"); /* UART setup entry */
196	
197	  if (initialized)
198	    {
199	      cold_ckpt("U4"); /* Already initialized */
200	      return OK;
201	    }
202	
203	  if (bk_uart_driver_init() != BK_OK)
204	    {
205	      cold_ckpt("E1"); /* Driver init failed */
206	      return -EIO;
207	    }
208	
209	  cold_ckpt("U1"); /* Driver init returned */
210	
211	  if (bk_uart_init(priv->id, &config) != BK_OK)
212	    {
213	      cold_ckpt("E2"); /* UART init failed */
214	      return -EIO;
215	    }
216	
217	  cold_ckpt("U2"); /* UART init returned */
218	
219	  /* NuttX owns the receive ring.  Keep bytes in the hardware FIFO so the SDK
220	   * callback can hand them directly to uart_recvchars().
221	   */
222	
223	  if (bk_uart_disable_sw_fifo(priv->id) != BK_OK)
224	    {
225	      cold_ckpt("E3"); /* FIFO disable failed */
226	      return -EIO;
227	    }
228	
229	  cold_ckpt("U3"); /* FIFO disabled */
230	
231	  if (bk_uart_set_rx_full_threshold(priv->id, 1) != BK_OK)
232	    {
233	      cold_ckpt("E4"); /* RX threshold failed */
234	      return -EIO;
235	    }
236	
237	  priv->rxbyte = -1;
238	  initialized = true;
239	  cold_ckpt("U4"); /* UART setup done */
240	  return OK;
241	}
