287	/****************************************************************************
288	 * Name: bk7258_uart_rxavailable / receive
289	 ****************************************************************************/
290	
291	static bool bk7258_uart_rxavailable(struct uart_dev_s *dev)
292	{
293	  struct bk7258_uart_s *priv = dev->priv;
294	
295	  if (priv->rxbyte < 0)
296	    {
297	      uint8_t byte;
298	      int nread;
299	
300	      nread = bk_uart_read_bytes(priv->id, &byte, 1, 0);
301	      priv->rxbyte = nread == 1 ? byte : -1;
302	    }
303	
304	  return priv->rxbyte >= 0;
305	}
306	
307	static int bk7258_uart_receive(struct uart_dev_s *dev, unsigned int *status)
308	{
309	  struct bk7258_uart_s *priv = dev->priv;
310	  int ch = priv->rxbyte;
311	
312	  priv->rxbyte = -1;
313	  if (status)
314	    {
315	      *status = 0;
316	    }
317	
318	  return ch;
319	}
