354	
355	static void bk7258_uart_txint(struct uart_dev_s *dev, bool enable)
356	{
357	  /* There is no TX interrupt; fake one by draining the ring synchronously
358	   * whenever the upper half enables transmission.  This makes the console
359	   * write path blocking-polled (matches the CMSDK polled fallback).
360	   */
361	
362	  if (enable)
363	    {
364	      uart_xmitchars(dev);
365	    }
366	}
