58	
59	/* Singleton SoC CPU1 control state.  The mutex serializes SYS register and
60	 * shared-state transitions issued by concurrent NSH callers.
61	 */
62	
63	static mutex_t g_bk7258_ap_lock = NXMUTEX_INITIALIZER;
64	static bool g_bk7258_ap_initialized;
