66	/****************************************************************************
67	 * Private Functions
68	 ****************************************************************************/
69	
70	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
71	{
72	  return (volatile uint32_t *)(uintptr_t)base;
73	}
74	
75	static void bk7258_cpu2_force_reset(void)
76	{
77	  volatile uint32_t *control =
78	    (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
79	
80	  *control &= ~BK7258_SYS_CPU2_RESET;
81	  __asm volatile ("dsb sy; isb sy" ::: "memory");
82	}
83	
84	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
85	{
86	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
87	  __asm volatile ("dsb sy" ::: "memory");
88	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
89	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
90	  __asm volatile ("dsb sy" ::: "memory");
91	}
92	
93	static void bk7258_ap_mbox_initialize(void)
94	{
95	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
96	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
97	
98	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
99	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
100	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
101	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
102	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
103	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
104	
105	  bk7258_ap_mbox_ack(to_ap);
106	  bk7258_ap_mbox_ack(to_cp);
107	}
108	
109	static void bk7258_ap_mbox_send(uint32_t event)
110	{
111	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
112	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
113	
114	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
115	       BK7258_MBOX_BOX0_BIT) != 0)
116	    {
117	      bk7258_ap_mbox_ack(mbox);
118	    }
119	
120	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
121	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
122	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
123	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
124	  __asm volatile ("dmb sy" ::: "memory");
125	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
126	  state->cp_to_ap_doorbells++;
127	  __asm volatile ("dsb sy; sev" ::: "memory");
128	}
129	
130	static uint32_t bk7258_ap_mbox_receive(void)
131	{
132	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
133	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
134	  uint32_t event = BK7258_AP_EVENT_NONE;
135	
136	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
137	       BK7258_MBOX_BOX0_BIT) != 0)
138	    {
139	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
140	          BK7258_AP_DOORBELL_MAGIC &&
141	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
142	        {
143	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
144	        }
145	
146	      bk7258_ap_mbox_ack(mbox);
147	    }
148	
149	  return event;
150	}
151	
152	static void bk7258_ap_state_prepare(void)
153	{
154	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
155	  uint32_t generation = 1;
156	
157	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
158	      state->version == BK7258_AP_BOOT_STATE_VERSION)
159	    {
160	      generation = state->generation + 1;
161	    }
162	
163	  memset((void *)(uintptr_t)state, 0,
164	         sizeof(struct bk7258_ap_boot_state_s));
165	  bk7258_ap_fault_state()->magic = 0;
166	  bk7258_cpu2_probe_state()->magic = 0;
167	  bk7258_ap_ipi_state()->magic = 0;
168	  bk7258_ap_smp_state()->magic = 0;
169	  bk7258_ap_affinity_state()->magic = 0;
170	  bk7258_ap_sem_wake_state()->magic = 0;
171	  bk7258_ap_sem_wake_loop_state()->magic = 0;
172	  bk7258_ap_bp2p_state()->magic = 0;
173	  bk7258_ap_bdul_state()->magic = 0;
174	  bk7258_ap_bmig_state()->magic = 0;
175	  bk7258_ap_btim_state()->magic = 0;
176	  bk7258_ap_blcy_state()->magic = 0;
177	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
178	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
179	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
180	  state->generation  = generation;
181	  state->command     = BK7258_AP_COMMAND_START;
182	  state->state       = BK7258_AP_STATE_STARTING;
183	  state->ram_start   = BK7258_AP_RAM_BASE;
184	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
185	  state->flash_start = BK7258_AP_FLASH_ADDR;
186	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
187	  __asm volatile ("dmb sy" ::: "memory");
188	}
