190	static bool bk7258_ap_scheduler_online(void)
191	{
192	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
193	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
194	    bk7258_cpu2_probe_state();
195	
196	  __asm volatile ("dmb sy" ::: "memory");
197	  return cpu2->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
198	         cpu2->version == BK7258_CPU2_PROBE_STATE_VERSION &&
199	         cpu2->size == sizeof(struct bk7258_cpu2_probe_state_s) &&
200	         cpu2->generation == state->generation &&
201	         cpu2->state == BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE &&
202	         cpu2->online_mask == 0x3u;
203	}
204	
205	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
206	{
207	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
208	  uint32_t elapsed;
209	  uint32_t event;
210	  bool first_iter = true;
211	
212	  if (timeout_ms == 0)
213	    {
214	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
215	    }
216	
217	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
218	    {
219	      event = bk7258_ap_mbox_receive();
220	      if (event != BK7258_AP_EVENT_NONE)
221	        {
222	          state->last_event = event;
223	        }
224	
225	      __asm volatile ("dmb sy" ::: "memory");
226	      if (state->state == wanted)
227	        {
228	          return OK;
229	        }
230	
231	      if (state->state == BK7258_AP_STATE_FAILED)
232	        {
