94		cnt_list->others_req_cnt = all_cnt - cnt_list->self_req_cnt;
95	
96		amp_res_sync[res_id].req_cnt[cpu_id]++;
97	
98		amp_exit_critical(int_mask);
99	
100		return BK_OK;
