180	bk_err_t amp_res_lock_acquire(u16 res_id, u32 timeout_ms, const char * func_name, int line_no)
181	{
182		bk_err_t	ret_val = BK_FAIL;
183	
184		if (!rtos_is_scheduler_started()) {
185			return BK_OK;
186		}
187	
188		if( rtos_is_in_interrupt_context() )
189		{
190			BK_LOGE("AMP", "can't call in ISR %s,%d\r\n", func_name, line_no);
191	
192			return BK_FAIL;
193		}
194	
195		if(res_id >= AMP_RES_ID_MAX)
196			return BK_ERR_PARAM;
197	
198		if(amp_res_sync[res_id].inited == 0)
199			return BK_ERR_NOT_INIT;
200	
201		amp_res_req_cnt_t	cnt_list;
202	
203	#ifdef AMP_RES_SERVER
204	
205		ret_val = amp_res_acquire_cnt(res_id, SELF_CPU, &cnt_list);
206	
207	#else
208	
209		ret_val = ipc_send_res_acquire_cnt(res_id, SELF_CPU, &cnt_list);
210	
211	#endif
212	
213		if(ret_val != BK_OK)
214		{
215			return ret_val;
216		}
217	
218		if((cnt_list.self_req_cnt == 0) && (cnt_list.others_req_cnt == 0))
219		{
220			/* resource is free, so set semaphore state to available. */
221			rtos_set_semaphore(&amp_res_sync[res_id].res_sema);
222	
223			amp_res_sync[res_id].owner_cpu = SELF_CPU;
224		}
225	
226		ret_val = rtos_get_semaphore(&amp_res_sync[res_id].res_sema, timeout_ms);
227	
228		if(ret_val != BK_OK)
229		{
230			/* timeout, someone holds the semaphore, so decrease the req_cnt before returns fail. */
231			bk_err_t ret_val2;
232			
233			ret_val2 = res_release_cnt(res_id, &cnt_list); /* decrease the req_cnt. */
234			
235			if(ret_val2 != BK_OK)
236				return ret_val;
237	
238			if(cnt_list.self_req_cnt == 0)
239			{
240				rtos_get_semaphore(&amp_res_sync[res_id].res_sema, 0); /* clear semaphore. */
241				/*
242				 *  should clear semaphore here.
243				 *  in case that semaphore is set 
244				 *  between get_semaphore is timeout  and res_release_cnt decreases the self_cnt to 0.
245				 */
246				
247				/* 
248				 *  the side effect may accidently cause someone fail to acquire resource
249				 *  during res_release_cnt decreases the self_cnt to 0 and call get_semaphore to clear the semaphore.
250				 */
251	
252				/* 
253				 * if not doing so, there may be the case that 2 tasks get permision to control the same resource.
254				 */
255			}
256		}
257	
258		return ret_val;
259	
260	}
261	
262	bk_err_t amp_res_lock_release(u16 res_id, const char * func_name, int line_no)
263	{
264		bk_err_t	ret_val = BK_FAIL;
265	
266		if (!rtos_is_scheduler_started()) {
267			return BK_OK;
268		}
269	
270		if( rtos_is_in_interrupt_context() )
271		{
272			BK_LOGE("AMP", "can't call in ISR %s,%d\r\n", func_name, line_no);
273	
274			return BK_FAIL;
275		}
276	
277		if(res_id >= AMP_RES_ID_MAX)
278			return BK_ERR_PARAM;
279	
280		if(amp_res_sync[res_id].inited == 0)
281			return BK_ERR_NOT_INIT;
282	
283		amp_res_req_cnt_t	cnt_list;
284	
285		ret_val = res_release_cnt(res_id, &cnt_list);
286	
287		if(ret_val != BK_OK)
288		{
289			return ret_val;
290		}
291	
292		if(cnt_list.self_req_cnt > 0)
293		{
294			/* other task is waiting for the resource, so unblock the task. */
295			rtos_set_semaphore(&amp_res_sync[res_id].res_sema);
296		}
297		else if(cnt_list.others_req_cnt > 0)
298		{
299			/* other CPU is waiting for the resource, so inform CPU that it is available. */
300			/* which CPU is selected in multi-cores? (over than 2 cores)*/
301			ret_val = ipc_send_available_ind(res_id);
302		}
303	
304		if(ret_val != BK_OK)
305		{
306			return ret_val;
307		}
308	
309		return ret_val;
310	
311	}
