1017	void sys_hal_clk_pwr_ctrl(dev_clk_pwr_id_t dev, dev_clk_pwr_ctrl_t power_up)
1018	{
1019		uint32_t v = 0;
1020		uint32_t offset = 0;
1021	
1022		if (dev >= CLK_PWR_ID_H264) {
1023			offset += CLK_PWR_ID_H264;
1024			v = sys_ll_get_reserver_reg0xd_value();
1025		} else {
1026			offset = 0;
1027			v = sys_ll_get_cpu_device_clk_enable_value();
1028		}
1029	
1030		if(CLK_PWR_CTRL_PWR_UP == power_up)
1031			v |= (1 << (dev - offset));
1032		else
1033			v &= ~(1 << (dev - offset));
1034	
1035		if (dev >= CLK_PWR_ID_H264) {
1036			sys_ll_set_reserver_reg0xd_value(v);
1037		} else {
1038			sys_ll_set_cpu_device_clk_enable_value(v);
1039		}
