150	static bk_err_t gpio_hal_map_check(gpio_hal_t *hal, gpio_id_t gpio_id)
151	{
152		const gpio_map_t *gpio_map = NULL;
153	
154		//special for BK7235:the GPIO ID isn't from 0~47, some of the GPIO are not exist.
155		for(int i = 0; i < sizeof(gpio_map_table)/sizeof(gpio_map_t); i++)
156		{
157			if(gpio_map_table[i].id == gpio_id)
158			{
159				gpio_map = &gpio_map_table[i];
160				break;
161			}
162		}
163		if(gpio_map == NULL)
164		{
165			HAL_LOGW("gpio id=%d is not exist\r\n", gpio_id);
166			return BK_ERR_GPIO_INVALID_ID;
167		}
168	
169		//TODO check gpio is busy
170		if(gpio_ll_check_func_mode_enable(hal->hw, gpio_id)) {
171			uint32 func_mode = gpio_ll_get_gpio_perial_mode((hal)->hw, gpio_id);
172			uint32 dev_use = gpio_map->dev[func_mode];
173	
174			HAL_LOGW("[gpio_log]:gpio:%d was busy: device num:0x%x!\r\n", gpio_id, dev_use);
175	
176			return BK_ERR_GPIO_INTERNAL_USED;
177		}
178	
179		return BK_OK;
180	}
