182	
183	bk_err_t gpio_hal_func_map(gpio_hal_t *hal, gpio_id_t gpio_id, gpio_dev_t dev)
184	{
185		GPIO_RETURN_ON_INVALID_ID(gpio_id);
186	
187		const gpio_map_t *gpio_map = NULL;
188	
189		//special for BK7235:the GPIO ID isn't from 0~47, some of the GPIO are not exist.
190		for(int i = 0; i < sizeof(gpio_map_table)/sizeof(gpio_map_t); i++)
191		{
192			if(gpio_map_table[i].id == gpio_id)
193			{
194				gpio_map = &gpio_map_table[i];
195				break;
196			}
197		}
198		if(gpio_map == NULL)
199		{
200			HAL_LOGW("gpio id=%d is not exist\r\n", gpio_id);
201			return BK_ERR_GPIO_INVALID_ID;
202		}
203	
204		if(gpio_hal_map_check(hal, gpio_id)) {
205			return BK_ERR_GPIO_INTERNAL_USED;
206		}
207	
208		//get peri mode of id
209		if (dev == GPIO_DEV_NONE) {
210			HAL_LOGW("gpio device is none, id=%d dev=%d\r\n", gpio_id, dev);
211			return BK_ERR_GPIOS_MAP_NONE;
212		} else {
213			for (int peri_func = 0; peri_func < GPIO_PERI_FUNC_NUM; peri_func ++) {
214				if (dev == gpio_map->dev[peri_func])
215					gpio_ll_set_gpio_perial_mode((hal)->hw, gpio_id, peri_func);
216			}
217		}
218	
219		// set gpio as second function mode
220		gpio_hal_output_enable(hal, gpio_id, 0);
221		gpio_hal_input_enable(hal, gpio_id, 0);
222		gpio_hal_pull_enable(hal, gpio_id, 0);
223		gpio_hal_sencond_function_enable(hal, gpio_id, 1);
224	
225		return BK_OK;
226	}
